/** Final-view selection; incoming construction remains exclusively in the request. */
type B1ViewControls=Omit<SkyControls,'incoming'>;
/** Frozen complete benchmark control, including the existing nine extra witnesses. */
type B1GpuControl=Omit<SkyGpuControl,'controls'>&{readonly controls:B1ViewControls;readonly horizonWitness:boolean};
/** Authenticated GPU host options for the contained B1 replay. */
type B1GpuHostOptions=Omit<SkyGpuHostOptions,'control'>&{readonly control:B1GpuControl};
/** Compiler report with separately integrated physical-order diagnostics. */
type B1GpuReport=SkyGpuChannelHeader['compilerReport']&{readonly pureRaySpectra:readonly (readonly number[])[]};
/** Channel header and immutable little-endian binary64 payload. */
type B1CapturedMetadata=Omit<SkyGpuChannelHeader,'compilerReport'>&{readonly compilerReport:B1GpuReport;readonly spectra:DialFileIdentity};
/** One retained complete channel. */
type B1CapturedChannel={readonly metadata:B1CapturedMetadata;readonly values:Float64Array};
/** Physical scalar comparison in common units. */
type B1ScalarRow={readonly label:string;readonly baseline?:number;readonly candidate?:number};
/** One authenticated complete Direct40 numerical case. */
type B1DiagnosticCase={readonly path:string;readonly seal:DialFileIdentity;readonly control:B1GpuControl;readonly channels:readonly B1CapturedChannel[]};
/** Registered ablations; the two existing factorial corners remain immutable. */
type B1Ablation='transport60'|'normalize40';
/** Independently integrated phase moments and the actual F68 response. */
type B1PhaseDiagnostic={g:number;reference:number[];coarse:number[];referenceCount:number;records:{index:number;mass:number;firstMoment:number;normalizedFirstMoment:number;secondMoment:number;normalizedSecondMoment:number}[];massMinimum:number;massMaximum:number;firstMomentRmse:number;normalizedFirstMomentRmse:number;scope:string};
/** Read-only paper scene metadata. */
type B1FigureScene={readonly time:string;readonly fileTime:string;readonly roundedSolarZenithDegrees:number};
/** Scientific PNG panel generated by the pinned paper renderer. */
type B1FigurePanel={readonly time:string;readonly png:Buffer;readonly rgbaSha256:string;readonly pngSha256:string;readonly score:{readonly rmseMilliwatt:number;readonly paperRoundedRmseMilliwatt:number}};
/** Authenticated unchanged published Figure5 image. */
type B1PublishedPanel={readonly time:string;readonly model:string;readonly path:string;readonly png:Buffer;readonly sha256:string};
/** Narrow explicit interface to the read-only historical paper renderer. */
type B1FigureApi={
 readonly FIGURE5_SCENES:readonly B1FigureScene[];
 readonly FIGURE5_ERROR_COLORS:readonly (readonly number[])[];
 loadPublishedFigure5Panels():readonly B1PublishedPanel[];
 renderAlgorithm32Figure5Panel(model:number[][][],measured:number[][][],scene:B1FigureScene):B1FigurePanel;
 renderFigure5ComparisonSvg(published:readonly B1PublishedPanel[],candidate:readonly B1FigurePanel[],provenance:unknown):string;
};
